mapper.sql:
SELECT DISTINCT gt.subject_id AS uid FROM grant_table gt WHERE gt.subject_type = 'USER' AND gt.role_code IN
#{rc}
UNION ALL
SELECT DISTINCT ud.user_id AS uid FROM grant_table gt JOIN user_dept ud ON ud.dept_id = gt.subject_id WHERE gt.subject_type = 'DEPT' AND ud.status = 0 AND gt.role_code IN
#{rc}
UNION ALL
SELECT DISTINCT up.user_id AS uid FROM grant_table gt JOIN user_post up ON up.post_id = gt.subject_id WHERE gt.subject_type = 'POST' AND (up.status IS NULL OR up.status = 0) AND gt.role_code IN
#{rc}

SELECT DISTINCT gt.subject_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM sys_role_permission rp INNER JOIN sys_permission p ON p.permission_code = rp.permission_code WHERE p.status = 1 AND rp.permission_code IN
#{pc}
) br ON br.role_code = gt.role_code WHERE gt.subject_type = 'USER' UNION ALL SELECT DISTINCT ud.user_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM sys_role_permission rp INNER JOIN sys_permission p ON p.permission_code = rp.permission_code WHERE p.status = 1 AND rp.permission_code IN
#{pc}
) br ON br.role_code = gt.role_code JOIN user_dept ud ON ud.dept_id = gt.subject_id WHERE gt.subject_type = 'DEPT' AND ud.status = 0 UNION ALL SELECT DISTINCT up.user_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM sys_role_permission rp INNER JOIN sys_permission p ON p.permission_code = rp.permission_code WHERE p.status = 1 AND rp.permission_code IN
#{pc}
) br ON br.role_code = gt.role_code JOIN user_post up ON up.post_id = gt.subject_id WHERE gt.subject_type = 'POST' AND (up.status IS NULL OR up.status = 0)

SELECT DISTINCT gt.subject_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM role_policy rp WHERE rp.is_deleted = 0 AND rp.policy_code IN
#{pcode}
) br ON br.role_code = gt.role_code WHERE gt.subject_type = 'USER' UNION ALL SELECT DISTINCT ud.user_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM role_policy rp WHERE rp.is_deleted = 0 AND rp.policy_code IN
#{pcode}
) br ON br.role_code = gt.role_code JOIN user_dept ud ON ud.dept_id = gt.subject_id WHERE gt.subject_type = 'DEPT' AND ud.status = 0 UNION ALL SELECT DISTINCT up.user_id AS uid FROM grant_table gt INNER JOIN ( SELECT DISTINCT rp.role_code FROM role_policy rp WHERE rp.is_deleted = 0 AND rp.policy_code IN
#{pcode}
) br ON br.role_code = gt.role_code JOIN user_post up ON up.post_id = gt.subject_id WHERE gt.subject_type = 'POST' AND (up.status IS NULL OR up.status = 0)
